//<auto-generated />
namespace ONEbook.UM.Transport
{
    using System;
    using System.Net;
    using System.Threading.Tasks;
    using Configurations;
    using Helpers;
    using RestSharp;

    public class UMRestClient : IUMRestClient
    {
        private readonly IRestClient restClient;

        public UMRestClient(UMClientConfiguration configuration = null, IRestClient restClient = null)
        {
            var umConfiguration = configuration ?? UMClientManager.UMClientConfigs;
            this.restClient = restClient ?? CreateDefaultClient(umConfiguration, new IPHelperImpl());
        }

        public static IRestClient CreateDefaultClient(UMClientConfiguration configuration, IPHelper ipHelper)
               => new RestClient
               {
                   BaseUrl = new Uri(configuration.ServiceUri),
                   Authenticator = new UMAuthenticator(configuration, ipHelper),
                   Timeout = 10000
               };

        public T ExecuteGet<T>(string endPoint) where T : new()
            => Execute<T>(endPoint, Method.GET, null);

        public T ExecutePost<T>(string endPoint, object data = null) where T : new()
            => Execute<T>(endPoint, Method.POST, data);

        public Task<T> ExecuteGetAsync<T>(string endPoint)
            => ExecuteAsync<T>(endPoint, Method.GET, null);

        public Task<T> ExecutePostAsync<T>(string endPoint, object data = null)
            => ExecuteAsync<T>(endPoint, Method.POST, data);

        private T Execute<T>(string endPoint, Method method, object data) where T: new ()
        {
            ValidateEndPoint(endPoint);

            var request = new RestRequest(endPoint, method);

            if (data != null)
            {
                request.AddJsonBody(data);
            }

            var response = restClient.Execute<T>(request);

            if (response.IsSuccessful)
            {
                return response.Data;
            }

            if (response.StatusCode == HttpStatusCode.ServiceUnavailable)
            {
                throw new Exception(response.Content);
            }

            throw new InvalidOperationException(
                string.Join(
                    "\r\n",
                    $"Status code: {response.StatusCode}",
                    $"Content: {response.Content}",
                    $"ErrorMessage: {response.ErrorMessage}"));
        }

        private async Task<T> ExecuteAsync<T>(string endPoint, Method method, object data)
        {
            ValidateEndPoint(endPoint);

            var request = new RestRequest(endPoint, method);

            if (data != null)
            {
                request.AddJsonBody(data);
            }

            var response = await restClient.ExecuteTaskAsync<T>(request).ConfigureAwait(false);

            if (response.IsSuccessful)
            {
                return response.Data;
            }

            if (response.StatusCode == HttpStatusCode.ServiceUnavailable)
            {
                await Task.FromException(new Exception(response.Content)).ConfigureAwait(false);
            }

            throw new InvalidOperationException(
                string.Join(
                    "\r\n",
                    $"Status code: {response.StatusCode}",
                    $"Content: {response.Content}",
                    $"ErrorMessage: {response.ErrorMessage}"));
        }

        private static void ValidateEndPoint(string endPoint)
        {
            if (string.IsNullOrWhiteSpace(endPoint))
            {
                throw new ArgumentNullException(nameof(endPoint));
            }
        }
    }
}